typedef struct {
    int *stack;
    int *inc;
    int top;
    int maxSize;
} CustomStack;

CustomStack* customStackCreate(int maxSize) {
    CustomStack *obj = (CustomStack*)malloc(sizeof(CustomStack));
    obj->stack = (int*)malloc(sizeof(int)*maxSize);
    obj->inc = (int*)calloc(maxSize, sizeof(int));
    obj->top = -1;
    obj->maxSize = maxSize;
    return obj;
}

void customStackPush(CustomStack* obj, int x) {
    if (obj->top + 1 < obj->maxSize) {
        obj->top++;
        obj->stack[obj->top] = x;
        obj->inc[obj->top] = 0;
    }
}

int customStackPop(CustomStack* obj) {
    if (obj->top == -1) return -1;
    int idx = obj->top;
    int res = obj->stack[idx] + obj->inc[idx];
    if (idx > 0) {
        obj->inc[idx-1] += obj->inc[idx];
    }
    obj->inc[idx] = 0;
    obj->top--;
    return res;
}

void customStackIncrement(CustomStack* obj, int k, int val) {
    int idx = k - 1;
    if (idx > obj->top) idx = obj->top;
    if (idx >= 0) {
        obj->inc[idx] += val;
    }
}

void customStackFree(CustomStack* obj) {
    free(obj->stack);
    free(obj->inc);
    free(obj);
}

